import type { editor } from "monaco-editor";
import type { OnMount } from "@monaco-editor/react";

import { ForwardedRef, useState } from "react";

export const useCodeBlockState = ({
  defaultHeight,
  defaultWidth,
  ref,
  onMount,
  id,
}: {
  defaultHeight: string;
  defaultWidth: string;
  ref: ForwardedRef<editor.IStandaloneCodeEditor>;
  onMount?: OnMount;
  id: string;
}) => {
  const [height] = useState(defaultHeight);
  const [width] = useState(defaultWidth);

  function handleEditorDidMount(
    editor: editor.IStandaloneCodeEditor,
    monaco: typeof import("monaco-editor"),
  ) {
    // Set the id on the textarea element
    const editorElement = editor.getDomNode();
    if (editorElement) {
      const textarea = editorElement.querySelector("textarea");
      if (textarea) {
        textarea.id = id;
      }
    }

    // Handle ref forwarding
    if (typeof ref === "function") {
      ref(editor);
    } else if (ref && "current" in ref) {
      ref.current = editor;
    }

    // Call user's onMount callback if provided
    if (onMount) {
      onMount(editor, monaco);
    }
  }

  return {
    handleEditorDidMount,
    height,
    width,
  };
};
